(() => {
  'use strict';
  const {stages,repositories,papers,connections}=window.HUB;
  const main=document.querySelector('#main');
  const dialog=document.querySelector('#repo-dialog');
  const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ext=(url,label,cls='text-link')=>`<a class="${cls}" href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)} <span aria-hidden="true">↗</span></a>`;
  const repo=name=>repositories.find(r=>r.name===name);
  const paper=id=>papers.find(p=>p.id===id);
  const repoButton=(name,label)=>`<button type="button" data-repo="${escape(name)}" class="repo-chip">${escape(label||repo(name)?.title||name)}</button>`;
  const researchLink=id=>`<a class="text-link" href="#thesis/${id==='synthesis'?'evidence':id}">Read the research <span aria-hidden="true">↗</span></a>`;
  const sectionLinks=(names,id)=>`<div class="section-links">${names.map(n=>`<button type="button" data-repo="${n}">${escape(repo(n).title)} ↗</button>`).join('')}${researchLink(id)}</div>`;
  const credit=n=>`Ranasinghe et al. (2025), <a href="https://doi.org/10.3390/s25216582" target="_blank" rel="noopener noreferrer">Sensors 25, 6582, Fig. ${n}</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Complete figure area cropped from the paper; results unchanged.`;
  let page='',lastTrigger=null;
  let filters={q:'',group:'all',type:'all',access:'all'};
  let selectedStage='calibrate';
  const svg=(body,label,w=400,h=240)=>`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${escape(label)}" xmlns="http://www.w3.org/2000/svg">${body}</svg>`;
  const schematicScene=(mode='fusion')=>{
    const colours=mode==='lidar'?['#628ac5','#628ac5','#628ac5']:['#a67746','#608fa2','#b9beab'];
    let dots='';for(let row=0;row<17;row++)for(let col=0;col<21;col++){const x=50+col*14+row*3,y=100+row*5-col*.6;dots+=`<circle cx="${x}" cy="${y}" r="1.5" fill="${colours[(row+col)%3]}"/>`}
    const scene=`<path d="M35 94l190-50 136 58-190 54z" fill="${mode==='lidar'?'#edf2fa':'#d4cfbd'}"/><path d="M35 94v89l136 39v-66z" fill="${mode==='lidar'?'#e2ebf7':'#a0b6c1'}"/><path d="M171 156l190-54v89l-190 31z" fill="${mode==='lidar'?'#ecf1f9':'#8ea7b3'}"/>`;
    const supports=[0,1,2,3,4].map(i=>`<path d="M${74+i*52} ${85-i*7}v${95+i*1.4}" stroke="${mode==='lidar'?'#a6bfdf':'#68849b'}" stroke-width="8"/>`).join('');
    return svg((mode==='lidar'?'':scene)+supports+(mode==='camera'?'':dots),`${mode} conceptual view of a supported underground space`);
  };
  const methodGraphics={
    spatial:()=>svg('<rect x="114" y="54" width="176" height="126" rx="5" fill="white" stroke="#a8bbd5"/>'+Array.from({length:6},(_,row)=>Array.from({length:8},(_,col)=>`<rect x="${116+col*21.5}" y="${56+row*20.5}" width="21.5" height="20.5" fill="${(row+col)%2?'#1c354f':'#fff'}"/>`).join('')).join('')+'<g fill="none" stroke="#2578d6" stroke-width="1.5"><path d="M48 205L137 77m-89 128 133-87m-133 87 178-46m-178 46 220-87"/><circle cx="137" cy="77" r="4"/><circle cx="181" cy="118" r="4"/><circle cx="226" cy="159" r="4"/></g><rect x="30" y="190" width="38" height="28" rx="5" fill="#1959c7"/><text x="190" y="224" text-anchor="middle" font-size="12" fill="#58718e" font-family="Arial">One paired capture · shared geometry</text>','Camera and LiDAR correspondences on a checkerboard'),
    enclosure:()=>svg('<path d="M114 189c0-150 186-150 186 0" stroke="#8da8c1" stroke-width="14" fill="none"/><path d="M36 79L147 139l144 70" stroke="#b9c7d9" stroke-dasharray="5 5" fill="none" stroke-width="2"/><path d="M36 79L147 139l150 21 64 40" stroke="#1959c7" fill="none" stroke-width="3"/><path d="M147 139l-30 38" stroke="#8097b3" stroke-dasharray="4 4"/><circle cx="36" cy="79" r="6" fill="#1959c7"/><g font-family="Arial" font-size="12" fill="#546e8c"><text x="147" y="52">Protective optical surface</text><text x="32" y="57">Light ray</text><text x="277" y="147">Refracted path</text></g>','A light ray changes direction as it passes through a dome'),
    timing:()=>svg('<g font-family="Arial" font-size="12" fill="#526d8b"><text x="34" y="65">Camera</text><text x="34" y="140">LiDAR</text><text x="153" y="211">Same event, different observation times</text></g><path d="M40 92H362M40 164H362" stroke="#bccbe0"/><path d="M42 91h46l27-30 34 59 30-56 25 27h128" fill="none" stroke="#1959c7" stroke-width="3"/><path d="M42 163h87l27-30 34 59 30-56 25 27h87" fill="none" stroke="#167870" stroke-width="3"/><path d="M149 118v58m41-56v58m-41-7h41" stroke="#7753ac" stroke-dasharray="3 3"/><text x="161" y="191" fill="#7753ac" font-family="Arial" font-size="13">Δt</text>','Two time series with an observation-time offset'),
    light:()=>svg('<rect x="26" y="43" width="158" height="155" rx="9" fill="#253041"/><rect x="216" y="43" width="158" height="155" rx="9" fill="#b8cad8"/><path d="M28 155l94-70 60 69m-93 4v-30m31-39v73m30-45v45" stroke="#4b5260" fill="none" stroke-width="5"/><path d="M219 155l94-70 60 69m-93 4v-30m31-39v73m30-45v45" stroke="#627f96" fill="none" stroke-width="5"/><path d="M192 122h17m-6-5 6 5-6 5" stroke="#1959c7" fill="none"/><g font-family="Arial" font-size="12" fill="#58718e"><text x="83" y="222">Raw image</text><text x="261" y="222">Enhanced image</text></g>','Conceptual low-light and enhanced views; not measured image data')
  };
  const methods=[
    {id:'spatial',label:'Spatial alignment',question:'Are we looking at the same place?',text:'Extrinsic calibration estimates how the two sensors are positioned relative to one another. It tells the software where a measured 3D point belongs in the image.',result:'A shared geometric frame',repos:['single-shot-lidar-camera-calibration'],paper:'spatial'},
    {id:'enclosure',label:'Enclosure correction',question:'Does the enclosure bend the measurement?',text:'A curved transparent dome refracts light. Ray tracing models this bending; correction tables and calibration with the enclosure in place address its effect on both sensing channels.',result:'Geometry that accounts for the optical surface',repos:['enclosure-aware-lidar-correction','lidar-enclosure-geometry'],paper:'measurement'},
    {id:'timing',label:'Observation timing',question:'Did both sensors see the same moment?',text:'A rotating target gives the sensors a common moving reference. Comparing its observed angle helps estimate a relative observation-time offset, even when timestamps alone are insufficient.',result:'An estimated offset between observations',repos:['livox-avia-camera-timing','rotating-target-calibration-studio'],paper:'timing'},
    {id:'light',label:'Low-light processing',question:'Can we recover useful appearance?',text:'Image enhancement makes dark scene information more visible, while colour correction and temporal smoothing help keep colourisation consistent. Performance depends on the platform and lighting conditions.',result:'More useful colour information under evaluated conditions',repos:['Sensor_Computer'],paper:'colour'}
  ];
  function methodPanel(id){const m=methods.find(x=>x.id===id);return `<div class="method-picture">${methodGraphics[id]()}</div><div><h3>${m.question}</h3><p>${m.text}</p><div class="method-result">↳ ${m.result}</div>${sectionLinks(m.repos,m.paper)}</div>`}
  function story(){
    return `<div class="hero container">
      <div class="hero-top"><div><div class="eyebrow">Sensing · Reconstruction · Safety</div><h1>From underground<br>observations to<br><em>spatial understanding.</em></h1></div><div class="hero-info"><p class="intro">A connected journey through LiDAR–camera research: seeing the mining face, making measurements reliable, and giving 3D observations meaning.</p><div class="actions"><a class="button" href="#story/context">Follow the story <span aria-hidden="true">↓</span></a><a class="text-link" href="#tools">Explore the tools ↗</a></div><div class="byline"><span class="byline-dot" aria-hidden="true"></span>Pasindu Ranasinghe · PhD research · UNSW Sydney</div></div></div>
      <figure class="hero-visual"><img src="public/assets/diagrams/longwall-story.svg" alt="Illustrated longwall: repeated roof supports face a coal wall, with a shearer and conveyor below and conceptual sensing cones beneath the canopy." width="1400" height="650"><div class="visual-topline"><span>A new perspective on underground monitoring</span><span>Longwall · conceptual geometry</span></div><figcaption class="visual-caption"><p><strong>See the space. Understand the relationships.</strong>Viewing cones illustrate a proposed arrangement. The drawing is a schematic, not a deployed system or measured point cloud.</p><span class="visual-pill">Explore the research ↓</span></figcaption></figure>
      <div class="journey-strip">${[['context','The challenge'],['capture','Capture'],['reliable','Calibrate'],['unit','Integrate'],['array','Reconstruct'],['safety','Interpret']].map((x,i)=>`<a href="#story/${x[0]}"><span>0${i+1}</span><b>${x[1]}</b></a>`).join('')}</div>
    </div>
    <section class="story-section container" id="story-context"><div class="section-heading"><div><div class="eyebrow">01 / The challenge</div><h2>A changing workplace.<br>A fragmented view.</h2></div><p>At a longwall face, a shearer cuts coal while a line of hydraulic supports protects the work area. Machinery, people and the surrounding geometry move together. Understanding their relationships needs more than isolated measurements.</p></div><div class="split"><div class="copy"><h3>What is near what?<br>And what is changing?</h3><p>Cameras show appearance, but distance and clearance are hard to judge from a flat view. Gas, dust, ground and worker-location sensors remain essential. Spatial sensing can add geometric context to their evidence.</p><div class="mini-points"><div><strong>Distance & clearance</strong><span>Where objects are relative to one another.</span></div><div><strong>Change over time</strong><span>How movement alters the scene.</span></div></div>${researchLink('review')}</div><figure><div class="illustration"><img src="public/assets/diagrams/longwall-story.svg" loading="lazy" alt="Conceptual supported longwall face with sensing views, roof supports and cutting machinery."></div><figcaption class="caption"><span class="caption-tag">An explanatory schematic</span>Proposed sensing beneath the canopy. Original illustration based on the supplied thesis context; no installed array is implied.</figcaption></figure></div></section>
    <section class="story-section container" id="story-capture"><div class="section-heading"><div><div class="eyebrow">02 / Capture</div><h2>Shape and colour.<br>A richer observation.</h2></div><p>A point cloud is a collection of measured 3D positions. Adding camera colour makes those points easier to interpret while preserving the LiDAR’s geometric information.</p></div><div class="fusion-grid"><div class="fusion-card">${schematicScene('camera')}<div><h3>Camera image</h3><p>Colour, texture and visual context.</p></div></div><span class="fusion-sign" aria-hidden="true">+</span><div class="fusion-card">${schematicScene('lidar')}<div><h3>LiDAR scan</h3><p>Distance measurements in 3D.</p></div></div><span class="fusion-sign" aria-hidden="true">→</span><div class="fusion-card">${schematicScene('fusion')}<div><h3>Colourised observation</h3><p>Geometry and appearance in one view.</p></div></div></div><p class="caption">Illustrative views explain fusion; the published examples below show actual research outputs.</p><div class="evidence-block"><div><span class="status-label">Published research output</span><h3>Useful appearance,<br>even under low light.</h3><p>These reconstructed corridor views compare dark, well-lit and enhanced dark captures from the four-camera research rig. This is a different platform from the later enclosed single-camera unit.</p>${sectionLinks(['Sensor_Computer'],'colour')}</div><figure><a class="image-zoom" href="public/assets/evidence/colourised-reconstruction.png" target="_blank" rel="noopener noreferrer" aria-label="Open full-resolution published colourised reconstruction figure"><img src="public/assets/evidence/colourised-reconstruction.png" alt="Complete published Figure 10, comparing SLAM corridor reconstruction under dark, well-lit and enhanced dark captures." loading="lazy"></a><figcaption class="caption">${credit(10)} Open the image to inspect every panel.</figcaption></figure></div></section>
    <section class="story-section container" id="story-reliable"><div class="section-heading"><div><div class="eyebrow">03 / Make it reliable</div><h2>Before combining views,<br>make them agree.</h2></div><p>Good-looking output is not enough. Spatial position, refraction, observation time and image quality each affect how reliably the sensors describe the same scene.</p></div><div class="method-lab"><div class="method-tabs" role="tablist" aria-label="Measurement reliability methods">${methods.map((m,i)=>`<button type="button" role="tab" id="method-tab-${m.id}" aria-controls="method-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-method="${m.id}">${m.label}</button>`).join('')}</div><div class="method-panel" id="method-panel" role="tabpanel" tabindex="0" aria-labelledby="method-tab-spatial">${methodPanel('spatial')}</div></div><p class="technical-note">These answer different questions. An estimated time offset is not the same as residual error after correction. Low-light performance and calibration results belong to the hardware and conditions actually evaluated.</p><details class="map-alt"><summary>See the published low-light comparison</summary><figure class="evidence-block"><div><h3>Raw → enhanced → smoothed</h3><p>The published sequence was captured at 1 lux. All four frames and all three rows are retained so the comparison remains in context.</p><figcaption class="caption">${credit(9)}</figcaption></div><a class="image-zoom" href="public/assets/evidence/low-light-comparison.png" target="_blank" rel="noopener noreferrer" aria-label="Open full-resolution low-light comparison"><img src="public/assets/evidence/low-light-comparison.png" alt="Complete published Figure 9: four camera frames at 1 lux, with raw, enhanced and temporally smoothed results." loading="lazy"></a></figure></details></section>
    <section class="story-section container" id="story-unit"><div class="section-heading"><div><div class="eyebrow">04 / Integrate</div><h2>A sensing method<br>becomes a physical unit.</h2></div><p>Putting sensors inside a protective enclosure changes the engineering problem. Optics, heat, power, computation and communications must work together.</p></div><div class="split"><figure><div class="device-visual"><img src="public/assets/diagrams/protected-unit.svg" alt="Original schematic of the unit architecture: optical dome above a LiDAR, camera and embedded processor, seated in an enclosure." loading="lazy"></div><figcaption class="caption"><span class="caption-tag">Architecture, illustrated</span>The source study integrates a solid-state LiDAR and one camera within a certified flameproof enclosure. This drawing is not an engineering specification.</figcaption></figure><div class="copy"><ol class="pipeline-list"><li><strong>Acquire</strong>Read LiDAR, images and inertial measurements.</li><li><strong>Correct and combine</strong>Apply appropriate calibration, timing and processing.</li><li><strong>Process within constraints</strong>Manage heat, data volume and embedded computation.</li><li><strong>Transmit a useful observation</strong>Send colourised point clouds and device diagnostics.</li></ol>${sectionLinks(['Sensor_Computer','3D_monitoring_device_simulation_underground'],'hardware')}<p class="caption">Bench testing and simulation establish pre-deployment evidence. Enclosure certification does not establish whole-system or site acceptance.</p></div></div></section>
    <section class="story-section container" id="story-array"><div class="section-heading"><div><div class="eyebrow">05 / Reconstruct</div><h2>Many local views.<br>One common scene.</h2></div><p>One device sees a local region. An array needs overlapping views, suitable mounting geometry and reliable alignment to build a wider scene.</p></div><div class="split"><div class="copy"><h3>A convincing fit<br>can still be the wrong fit.</h3><p>Repeated roof supports look similar. Aligning surfaces alone can place a device in the wrong position. The array research uses known spacing as a physical constraint, alongside roof-plane alignment and global pose optimisation.</p><p>A pose graph is a network of device positions and their alignment relationships. Optimising it helps organise neighbouring observations into a common frame.</p>${sectionLinks(['Lidar_camera_FOV_analysis','Multi_device_reconstruction-pose_graph'],'array')}<p class="caption">Array registration was evaluated in simulated longwall trials. Surveyed multi-unit operating-face validation remains a next step.</p></div><div class="dark-panel"><span class="status-label" style="color:#98c9e5">The operator’s view</span><h3>From streams to an inspectable scene.</h3><p>The Central Monitoring Platform receives individual device streams and provides combined viewing, recording, measurements and diagnostics.</p><div class="interface-schematic"><div class="interface-toolbar"><span>Central monitoring · interface concept</span><span>3D view</span></div><div class="interface-body"><div class="interface-sidebar"><span>◉ Reconstruction</span><span>○ Device 01</span><span>○ Device 02</span><span>○ Device 03</span><span>IMU · temperature</span></div><img src="public/assets/diagrams/longwall-story.svg" alt="Schematic of a combined scene in an illustrative monitoring interface." loading="lazy"></div></div><p class="caption">Original interface schematic; not an application screenshot. Features are documented in the supplied user guide v3.</p><div class="section-links"><button type="button" data-repo="Central_Monitoring_Platform" style="color:#a9cff7">Explore the desktop platform ↗</button></div></div></div></section>
    <section class="story-section container" id="story-safety"><div class="section-heading"><div><div class="eyebrow">06 / Interpret</div><h2>Seeing an object<br>is only the beginning.</h2></div><p>Safety interpretation asks what objects mean in relation to one another. The research combines perception with structured relationships, deterministic rules and contextual reasoning.</p></div><div class="reasoning-flow"><div><small>OBSERVE</small><strong>3D point clouds</strong><p>Measured positions and colour.</p></div><div><small>DETECT</small><strong>Scene elements</strong><p>Semantic classes and uncertainty signals.</p></div><div><small>RELATE</small><strong>Scene & temporal graphs</strong><p>Objects, distances and changing relationships.</p></div><div><small>INTERPRET</small><strong>Hazard evidence</strong><p>Rules, context and relevant history.</p></div></div><div class="scenario"><div><span class="status-label" style="color:var(--purple)">An illustrative proximity scenario</span><h3>A person near moving equipment.</h3><p>Perception locates the person and machinery. A spatial relationship supports a proximity rule; context and historical evidence can help explain the situation. No fictional distance or safety threshold is used here.</p>${sectionLinks(['Scene-Graph_Mine-Safety'],'safety')}</div><div>${safetyGraph()}<p class="caption">Conceptual example grounded in the research’s personnel–equipment hazard class. This is an explanation, not a live alert or measured scenario output.</p></div></div><div class="evidence-numbers"><div><strong>115</strong><span>controlled hazard scenarios</span></div><div><strong>57 → 76 → 93%</strong><span>reported coverage: rules → contextual reasoning → memory</span></div></div><p class="technical-note">Scenario coverage is separate from perception accuracy and processing throughput. MineGraph Studio demonstrates one-frame inspection; it does not connect to live sensors or implement the full temporal research pipeline. The reconstructed-array-to-reasoning connection remains proposed.</p></section>
    <section class="story-section container" id="story-extensions"><div class="section-heading"><div><div class="eyebrow">07 / Further applications</div><h2>More questions<br>from the same geometry.</h2></div><p>Once 3D observations are available, other tools can explore movement and shape. Each has its own purpose and evidence boundary.</p></div><div class="extensions">${[['Creep_Monitoring','↝','Concept / prototype','Gradual relative movement','Track relative roof-support displacement using reference markers and recorded scans. Operating-face creep performance is not established.'],['Dynamic_Object_Detection','◎','Supporting tool','Motion in a persistent scene','Identify moving foreground points while accounting for a stationary or slightly moving sensor. Named monitoring integration remains unverified.'],['Meshing_toolkit','△','Research toolkit','From points to surfaces','Build coloured surface meshes and benchmark scan consistency. A mesh is a representation of the available observations, not additional measured geometry.']].map(x=>`<article class="extension"><span class="icon" aria-hidden="true">${x[1]}</span><span class="status-label">${x[2]}</span><h3>${x[3]}</h3><p>${x[4]}</p><div class="section-links"><button type="button" data-repo="${x[0]}">Explore this application ↗</button></div></article>`).join('')}</div></section>
    <section class="closing container"><div class="eyebrow" style="justify-content:center">The bigger picture</div><h2>A connected research programme.<br>A staged path to validation.</h2><p>Explore how the tools support one another, or follow the academic evidence through the thesis. Separate studies establish the building blocks; sustained, integrated underground trials remain future work.</p><div class="actions"><a class="button" href="#tools">Explore the tools <span aria-hidden="true">↗</span></a><a class="button secondary" href="#thesis">Read the thesis map <span aria-hidden="true">↗</span></a></div></section>`;
  }
  function safetyGraph(){return svg('<g stroke="#a996c6" stroke-width="2" fill="none"><path d="M95 105H296M93 105L199 203m97-98-97 98M93 105l107-77 96 77"/></g><g font-family="Arial,sans-serif" text-anchor="middle"><rect x="21" y="78" width="143" height="55" rx="14" fill="white" stroke="#b5a5d0"/><text x="93" y="110" fill="#584578" font-size="16">Person</text><rect x="229" y="78" width="142" height="55" rx="14" fill="white" stroke="#b5a5d0"/><text x="300" y="110" fill="#584578" font-size="16">Equipment</text><rect x="147" y="180" width="111" height="46" rx="13" fill="#d7caea"/><text x="202" y="208" fill="#584578" font-size="14">Rule evidence</text><rect x="141" y="6" width="124" height="44" rx="13" fill="#d7caea"/><text x="203" y="33" fill="#584578" font-size="14">Scene context</text><rect x="163" y="91" width="67" height="26" rx="13" fill="#efecf6"/><text x="197" y="109" fill="#786391" font-size="12">near</text></g>','Illustrative graph linking a person and equipment with a near relationship, scene context and rule evidence')}
  function tools(){return `<div class="container"><div class="page-intro"><div class="eyebrow">The research ecosystem</div><h1>Explore the tools.<br>Understand the connections.</h1><p class="intro">Fifteen repositories support a shared research story. Some exchange data, some share methods, and some suggest future workflows. Select a stage to see the difference.</p></div><section class="map-shell" aria-labelledby="map-title"><div class="map-heading"><div><h2 id="map-title">From observation to interpretation</h2><p>The stage layout describes the research progression; detailed connections below identify the actual evidence.</p></div><div class="legend" aria-label="Connection legend"><span><i></i>Documented interface</span><span><i class="method"></i>Shared method / support</span><span><i class="future"></i>Proposed connection</span></div></div><div class="stage-map"><svg class="map-line" viewBox="0 0 1000 380" preserveAspectRatio="none" aria-hidden="true"><path data-for="capture calibrate" class="connection-active" d="M220 95H500" fill="none" stroke="#167870" stroke-dasharray="6 5" stroke-width="2"/><path data-for="calibrate protect" class="connection-active" d="M560 95H860" fill="none" stroke="#167870" stroke-dasharray="6 5" stroke-width="2"/><path data-for="protect reconstruct" d="M855 97Q988 100 988 180T855 285" fill="none" stroke="#1959c7" stroke-width="2"/><path data-for="reconstruct interpret" d="M840 286H550" fill="none" stroke="#ab572e" stroke-dasharray="2 5" stroke-width="2"/><path data-for="interpret extend" d="M480 286H180" fill="none" stroke="#ab572e" stroke-dasharray="2 5" stroke-width="2"/></svg>${stages.map((s,i)=>`<button type="button" class="stage-node" data-stage="${s.id}" aria-pressed="${s.id===selectedStage}" aria-controls="map-detail"><span class="node-num">0${i+1}</span><strong>${s.title}</strong><small>${s.subtitle}</small></button>`).join('')}</div><div id="map-detail" class="map-detail" aria-live="polite">${stageDetail(selectedStage)}</div><details class="map-alt"><summary>Accessible text view of all repository connections</summary><ol>${connections.map(c=>`<li><strong>${escape(c.from)} → ${escape(c.to)}</strong><br>${escape(c.label)} · ${kindLabel(c.kind)}. ${escape(c.basis)}</li>`).join('')}</ol></details></section><section aria-labelledby="catalogue-title"><div class="catalogue-heading"><h2 id="catalogue-title">Find your next tool.</h2><span class="repo-count" id="repo-count" aria-live="polite">15 repositories</span></div><div class="filters"><div class="filter-field"><label for="repo-search">Search tools, inputs or methods</label><input id="repo-search" type="search" placeholder="Try calibration, point clouds, timing…" value="${escape(filters.q)}"></div><div class="filter-field"><label for="type-filter">Interface</label><select id="type-filter"><option value="all">All interfaces</option>${[...new Set(repositories.map(r=>r.type))].map(t=>`<option${filters.type===t?' selected':''}>${t}</option>`).join('')}</select></div><div class="filter-field"><label for="access-filter">Code access</label><select id="access-filter"><option value="all">All repositories</option><option value="public"${filters.access==='public'?' selected':''}>Publicly accessible</option><option value="private"${filters.access==='private'?' selected':''}>Summary-recorded private</option></select></div></div><div class="group-tabs" role="group" aria-label="Filter by research area">${[['all','All tools'],['calibration','Calibration'],['sensing','Sensing'],['reconstruction','Reconstruction'],['interpretation','Interpretation'],['extensions','Further applications']].map(x=>`<button type="button" data-group="${x[0]}" aria-pressed="${filters.group===x[0]}">${x[1]}</button>`).join('')}</div><div class="repo-grid" id="repo-grid">${repositoryCards()}</div></section></div>`}
  const kindLabel=k=>({interface:'Documented data interface',method:'Shared method / supporting tool',future:'Proposed future connection'}[k]);
  function connectionHTML(c,compact=false){return `<li class="connection-item ${c.kind}"><strong>${escape(c.label)}</strong><span>${escape(c.from)} → ${escape(c.to)}</span><span>${kindLabel(c.kind)}${compact?'':` · ${escape(c.basis)}`}</span></li>`}
  function stageDetail(id){const s=stages.find(x=>x.id===id),edges=connections.filter(c=>s.repos.includes(c.from)||s.repos.includes(c.to));return `<div><h3>${s.subtitle}</h3><p>${s.description}</p><div class="map-output">Output: ${s.output}</div><div class="repo-chips">${s.repos.map(n=>repoButton(n)).join('')}</div><div class="section-links">${researchLink(s.paper)}</div></div><div><h4 style="font-size:.85rem;letter-spacing:0">Relevant relationships</h4><ul class="connection-list">${edges.slice(0,4).map(c=>connectionHTML(c,true)).join('')}</ul>${edges.length>4?`<details class="map-alt"><summary>${edges.length-4} more connections</summary><ul class="connection-list">${edges.slice(4).map(c=>connectionHTML(c,true)).join('')}</ul></details>`:''}</div>`}
  function selectStage(id){selectedStage=id;document.querySelectorAll('[data-stage]').forEach(t=>t.setAttribute('aria-pressed',String(t.dataset.stage===id)));document.querySelector('#map-detail').innerHTML=stageDetail(id);document.querySelectorAll('.map-line path').forEach(p=>p.classList.toggle('connection-active',p.dataset.for.split(' ').includes(id)));}
  function accessInfo(r){const v=window.REPOSITORY_STATUS[r.name];return v||{public:r.visibility==='Public',licence:'Unverified',reviewDate:'2026-10-08'}}
  function filtered(){return repositories.filter(r=>{const v=accessInfo(r);return(filters.group==='all'||r.group===filters.group)&&(filters.type==='all'||r.type===filters.type)&&(filters.access==='all'||(filters.access==='public'?v.public:!v.public))&&[r.title,r.name,r.problem,r.approach,r.inputs,r.outputs].join(' ').toLowerCase().includes(filters.q.toLowerCase().trim())})}
  function repositoryCards(){const list=filtered();return list.length?list.map(r=>{const v=accessInfo(r);return `<article class="repo-card"><span class="repo-symbol" aria-hidden="true">${({calibration:'⌖',sensing:'◈',reconstruction:'▱',interpretation:'⌘',extensions:'↝'})[r.group]}</span><h3>${r.title}</h3><p>${r.problem}</p><div class="repo-meta"><span>${r.type}</span><span class="${v.public?'public':'private'}">${v.public?'Public code':'Private in summary'}</span></div><button type="button" class="repo-open" data-repo="${r.name}" aria-label="Explore ${escape(r.title)}">Explore tool <span aria-hidden="true">↗</span></button></article>`}).join(''):`<p class="no-results">No tools match these filters. <button type="button" class="repo-chip" data-reset-filters>Clear filters</button></p>`}
  function refreshCards(){document.querySelector('#repo-grid').innerHTML=repositoryCards();document.querySelector('#repo-count').textContent=`${filtered().length} of 15 repositories`;document.querySelectorAll('[data-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.group===filters.group)))}
  function repositoryImage(r){if(r.name==='rotating-target-calibration-studio')return `<figure class="dialog-image"><a class="image-zoom" href="public/assets/evidence/rotating-target-studio.png" target="_blank" rel="noopener noreferrer"><img src="public/assets/evidence/rotating-target-studio.png" alt="Real face-on rotating-target studio screenshot showing the apertured disc, rotation direction and simulated angle."></a><figcaption class="caption">Rotating Target Calibration Studio documentation screenshot ? Pasindu Ranasinghe, UNSW (2026). <a href="public/assets/evidence/rotating-target-studio.LICENSE.txt">MIT licence notice</a>. Noise-free simulated geometry; the displayed angle is not measured hardware timing accuracy.</figcaption></figure>`;if(r.name==='single-shot-lidar-camera-calibration')return `<figure class="dialog-image"><img src="public/assets/evidence/registration-validation.png" alt="Published alignment and projection validation panels from the related colourisation study."><figcaption class="caption">Related enabling-method research, not a screenshot of this repository. ${credit(8)}</figcaption></figure>`;if(r.name==='Sensor_Computer')return `<figure class="dialog-image"><img src="public/assets/evidence/multi-camera-prototype.png" alt="The published four-camera research rig on a trolley."><figcaption class="caption">Earlier four-camera platform, distinct from this repository’s enclosed single-camera unit. ${credit(1)}</figcaption></figure>`;return ''}
  function openRepository(name,trigger){const r=repo(name);if(!r)return;if(page==='tools')selectStage((stages.find(s=>s.repos.includes(name))||stages[0]).id);if(!dialog.open)lastTrigger=trigger||document.activeElement;const v=accessInfo(r),edges=connections.filter(c=>c.from===name||c.to===name);const demo=v.demo&&/^https:\/\//.test(v.demo)?v.demo:null;
    document.querySelector('#dialog-content').innerHTML=`<div class="dialog-head"><span>${r.type} · ${r.group}</span><button type="button" class="close-button" data-close-dialog aria-label="Close tool details">×</button></div><div class="dialog-body"><h2 id="dialog-title">${r.title}</h2><code class="exact-name">${r.name}</code><p>${r.problem}</p><h3>The approach</h3><p>${r.approach}</p>${repositoryImage(r)}<div class="detail-grid"><div><h3>Inputs</h3><p>${r.inputs}</p></div><div><h3>Outputs</h3><p>${r.outputs}</p></div><div><h3>Role in the story</h3><p>${r.role}</p></div><div><h3>Evidence & development</h3><p>${r.status}</p></div></div><h3>Related tools</h3><ul class="connection-list">${edges.map(c=>connectionHTML(c)).join('')||'<li>No direct repository connection is documented.</li>'}</ul><div class="repo-chips">${r.related.map(n=>repoButton(n)).join('')}</div><h3 style="margin-top:2rem">The research</h3><ul class="paper-links">${r.papers.map(id=>id==='synthesis'?'<li><a href="#thesis/evidence" data-dialog-nav>Chapter 7 · Synthesis, limitations and future validation ↗</a></li>':`<li><a href="#thesis/${id}" data-dialog-nav>${paper(id).chapter} · ${paper(id).label} ↗</a></li>`).join('')}</ul><p class="source-note"><strong>Code access:</strong> ${v.public?'Publicly accessible, checked 8 October 2026.':'Recorded as private in the supplied overview. Anonymous access is unavailable; current details cannot be verified.'}<br><strong>Licence:</strong> ${escape(v.licence)}${v.licenceUrl?` · ${ext(v.licenceUrl,'Read terms','')}`:''}<br>Public access and permission to reuse code are separate. ${v.public?'Descriptions checked against the public README.':'Description based on the supplied portfolio and applicable local research documents.'}</p><div class="actions">${ext(`https://github.com/maninka123/${name}`,v.public?'View repository':'GitHub · authorised access','button')}${demo?ext(demo,'Open browser demo','button secondary'):''}${v.readme?ext(v.readme,'Documentation','text-link'):''}</div></div>`;
    if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.querySelector('[data-close-dialog]').focus();
  }
  function closeDialog(){dialog.close();if(lastTrigger?.isConnected)lastTrigger.focus()}
  const thesisSections=[['overview','Overview & objectives'],['chapters','Chapter sequence'],['papers','Paper register'],['mapping','Software mapping'],['evidence','Evidence & limitations'],['reproducibility','Reproducibility'],['appendices','Appendices & future work']];
  function paperEntry(p){const related=repositories.filter(r=>r.papers.includes(p.id));return `<article class="paper-entry" id="paper-${p.id}"><span class="paper-slot">${p.chapter.includes('Appendix')?p.chapter:'Chapter '+p.chapter} · ${p.label}</span><h3>${p.title}</h3><p class="paper-authors">${p.authors}</p><p>${p.venue}</p><p class="paper-status">${p.status}</p><p class="contribution"><strong>Distinct contribution.</strong> ${p.contribution}</p><p><strong>Validation setting.</strong> ${p.evidence}</p>${p.versionNote?`<p>${p.versionNote}</p>`:''}${related.length?`<div class="repo-chips">${related.map(r=>repoButton(r.name)).join('')}</div>`:''}${p.url?ext(p.url,p.id==='hardware'?'Read earlier public preprint':'Read paper / public record'):''}</article>`}
  function thesis(){return `<div class="container"><div class="page-intro thesis-title"><div class="eyebrow">An academic view</div><h1>Integrated LiDAR–camera sensing.<br>From methods to safety reasoning.</h1><p class="intro">Thesis by publication · Pasindu Ranasinghe<br>School of Minerals and Energy Resources Engineering · UNSW Sydney</p><p class="caption">Seven chapters; eight main-body studies and a ninth in Appendix A. Structure follows the September 2026 plan, with identified public-record updates.</p></div><div class="academic-grid"><nav class="academic-nav" aria-label="Thesis sections"><span class="label">The thesis map</span>${thesisSections.map(x=>`<a href="#thesis/${x[0]}">${x[1]}</a>`).join('')}</nav><div class="academic-body"><section id="thesis-overview"><h2>Overview & research objectives</h2><p>The thesis develops a pathway from reliable enclosed LiDAR–camera observations to spatial reconstruction and safety interpretation for longwall operations. Requirements motivate enabling methods; engineering integrates the unit; array reconstruction supplies wider spatial context; perception and reasoning interpret the scene.</p><ol class="objectives"><li><strong>Design and build a sensing unit</strong> for continuous longwall face monitoring. Principal evidence: Chapter 4.</li><li><strong>Calibrate the unit and develop accurate, real-time colourised 3D processing.</strong> Methods in Chapter 3; implementation in Chapters 4–5.</li><li><strong>Deploy multiple units as an array and interpret the reconstructed scene</strong> for underground safety decision support. Chapters 5–6 establish capabilities through pre-deployment and controlled evidence; operating-face deployment remains to be validated.</li></ol><div class="boundary"><h3>What the programme establishes</h3><p>Analytical, laboratory, recorded-data, simulation and controlled-scenario evidence for separate stages. It does not establish sustained end-to-end operation on an active underground longwall face.</p></div></section><section id="thesis-chapters"><h2>The chapter sequence</h2><ol class="chapter-list">${[['Introduction','Problem, research gap, objectives and distinct contributions.'],['Literature review','Monitoring requirements and deployment-readiness criteria.'],['Enabling methods for enclosed sensing','3.1 Spatial calibration · 3.2 Enclosure and timing · 3.3 Temporal target · 3.4 Colourisation.'],['A unit within a certified flameproof enclosure','Physical integration, thermal constraints and pre-deployment validation.'],['Scaling to a face-wide array','Efficient processing, coverage, spacing-constrained alignment and reconstruction.'],['From 3D perception to safety reasoning','Perception, uncertainty, graph representation, rules, contextual reasoning and memory.'],['Discussion and conclusions','Cross-study synthesis, readiness, limitations and future validation.']].map((x,i)=>`<li><span class="ch">0${i+1}</span><div><strong>${x[0]}</strong><small>${x[1]}</small></div></li>`).join('')}</ol></section><section id="thesis-papers"><h2>Paper register & distinct contributions</h2><p>Publication records and software evolve independently. Local manuscript titles and evidence are preserved; linked preprints may be earlier versions. Candidate and co-author contribution statements require final author records.</p>${papers.map(p=>paperEntry(p)).join('')}</section><section id="thesis-mapping"><h2>Repositories, papers & chapters</h2><p>Shared support does not imply a live interface or an independently novel contribution in every chapter.</p><div class="table-wrap"><table><thead><tr><th>Repository</th><th>Research location</th><th>Role</th></tr></thead><tbody>${repositories.map(r=>`<tr><td><button type="button" data-repo="${r.name}">${r.name}</button></td><td>${r.papers.map(id=>id==='synthesis'?'Chapter 7 / supporting work':paper(id).chapter).join(', ')}</td><td>${r.role}</td></tr>`).join('')}</tbody></table></div></section><section id="thesis-evidence"><h2>Validation settings & limitations</h2><div class="table-wrap"><table><thead><tr><th>Research claim</th><th>Documented evidence</th><th>Interpretation limit</th></tr></thead><tbody><tr><td>Enclosure-aware calibration</td><td>Ray tracing, physics simulation and laboratory corrections.</td><td>The ~43% refraction improvement is shared with Appendix A, not independent replication.</td></tr><tr><td>Temporal estimation</td><td>Measurement: ~32 ms initial error, 2.726 ms corrected residual. Rotating target: +66.7 ms estimated relative observation-time offset.</td><td>Different metrics and experimental setups; these are not comparable accuracy measures.</td></tr><tr><td>Temporal target transfer</td><td>22 configurations, three hardware configurations, the rest simulated.</td><td>Do not describe 22 physical experiments. Browser simulation is idealised.</td></tr><tr><td>Protected unit</td><td>Bench/thermal tests; optical calibration; representative longwall simulation. 10 Hz standard output and 5.2 Hz enhanced output under the reported conditions.</td><td>Certified enclosure scope differs from system/site acceptance. Sustained underground duty remains to be tested.</td></tr><tr><td>Array alignment</td><td>1,029 simulated neighbouring-device trials; ~1° rotation and &lt;0.1 m cross-axis pairwise error under tested constraints.</td><td>Pairwise cross-axis errors do not establish global operational accuracy; spacing sensitivity matters.</td></tr><tr><td>Perception</td><td>92.7% overall accuracy, mIoU 0.86 and 30.2 FPS on the local manuscript evaluation.</td><td>Perception throughput is separate from sensor output and end-to-end latency.</td></tr><tr><td>Hazard reasoning</td><td>115 controlled scenarios: 57% rules, 76% with context, 93% with relevant memory.</td><td>Scenario coverage is not operational safety efficacy or measured field alert performance.</td></tr><tr><td>Creep monitoring</td><td>Marker-based and IMU-supported concepts/prototype recorded in the portfolio.</td><td>Not an independently validated operational support-movement system.</td></tr></tbody></table></div><p class="caption">Metrics are reported from the current local papers and completion plan. Definitions, test conditions and denominators must accompany formal citation.</p><div class="boundary"><h3>Integration remains a research question</h3><p>The protected unit, array and safety framework have separately documented evaluation settings. Direct use of Chapter 5 reconstructed outputs in Chapter 6 is not established. MineGraph Studio’s one-frame demo omits temporal graphs and live system integration.</p></div></section><section id="thesis-reproducibility"><h2>Software & reproducibility</h2><p>Public repositories provide implementations and instructions, with different licences. Six repositories are recorded as private and cannot be verified anonymously. Browsable source does not imply open-source licensing: Sensor_Computer is explicitly proprietary.</p><p>For examination, Appendix D should map each software or data package to a fixed release/commit, dependency record, usage instructions and the results it supports. GitHub links alone are not a fixed examination archive. Confidential mine data and partner material need separate release decisions.</p><p>This hub contains dated access/licence records and an asset register. It does not redistribute private repository code or the original manuscripts.</p><a class="text-link" href="#sources">Inspect the sources & attribution record ↗</a></section><section id="thesis-appendices"><h2>Appendices & future work</h2><ul class="appendix-list"><li><strong>Appendix A:</strong> Earlier dome-refraction paper, with overlap to Section 3.2 disclosed.</li><li><strong>Appendix B:</strong> Literature-review audit, search criteria and supporting maturity classification.</li><li><strong>Appendix C:</strong> Verified application documentation. The supplied v3 manual now describes Central Monitoring application 1.0.1; earlier planning notes about missing manuals are stale.</li><li><strong>Appendix D:</strong> Fixed software/data archives and reproducibility records.</li><li><strong>Appendix E:</strong> Other supporting paper appendices, simulator/data specifications and permitted patent material.</li></ul><p>Next validation stages: single-unit underground testing; surveyed multi-unit reconstruction; environmental robustness and sustained duty; then joint acquisition-to-reasoning trials with operational error and human-use evaluation. These are proposed future stages, not completed deployment milestones.</p><p>Patent identifiers recorded in the plan: 2026902579 and 202411295521.4. Inventors, jurisdiction, status and permitted disclosure are not independently verified here.</p></section></div></div></div>`}
  function sources(){return `<div class="container sources"><div class="page-intro"><div class="eyebrow">Inspectable evidence</div><h1>Sources & image credits.</h1><p class="intro">The story is grounded in the supplied thesis documents, published research and public repository documentation. Diagrams explain concepts; evidence images retain the original scientific panels.</p></div><h2>Content sources</h2><ul><li>GitHub Repository Portfolio Overview: all 15 initial repository descriptions and private-tool summaries.</li><li>Thesis completion plan and skeleton, September 2026; Chapter Map and Thesis Storyline: chapter ownership, objectives, contributions and evidence boundaries.</li><li>Current journal/conference papers: platform distinctions, evaluation settings and metrics.</li><li>Central Monitoring Platform user guide v3: application 1.0.1, documented transports and operator functions.</li><li>Public GitHub READMEs and licence records, checked 8 October 2026: access, current documentation, supported interfaces and limitations.</li><li>${ext('https://research.unsw.edu.au/people/professor-simit-raval/publications','UNSW Research publication record','')}: current safety journal citation, superseding the local plan’s under-review status. ${ext('https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7513129','SSRN rotating-target preprint','')}: a public paper link missing from the older plan.</li></ul><h2>Published evidence images</h2>${[['1','multi-camera-prototype','Four-camera research prototype','The trolley rig is distinct from the protected single-camera mine unit.'],['8','registration-validation','Alignment and projection validation','Complete original calibration panels retained.'],['9','low-light-comparison','Raw, enhanced and smoothed images','Four frames at 1 lux; all three comparison rows retained.'],['10','colourised-reconstruction','Colourised corridor reconstruction','Dark, well-lit and enhanced dark captures; all comparison panels retained.']].map(x=>`<article class="source-card"><h3>${x[2]}</h3><p>${x[3]}</p><p>${credit(x[0])}</p>${ext(`public/assets/evidence/${x[1]}.png`,'Inspect full-resolution figure')}</article>`).join('')}<article class="source-card"><h3>Rotating-target studio screenshot</h3><p>Genuine face-on simulation view from the public studio README. Pasindu Ranasinghe, UNSW (2026). Used under <a href="public/assets/evidence/rotating-target-studio.LICENSE.txt">MIT with complete notice</a>; image unmodified. Noise-free simulated target geometry, not physical calibration accuracy.</p><a class="text-link" href="public/assets/evidence/rotating-target-studio.png" target="_blank" rel="noopener noreferrer">Inspect screenshot ?</a></article><h2>Original explanatory diagrams</h2><p>The longwall, protected-unit, fusion, calibration and relationship schematics were created for this hub from the supplied scientific concepts. They are editable SVGs and are explicitly illustrative. No generated scientific result, fictional measurement or field-deployment photograph is used.</p><p>Partner hardware photographs, confidential mine reconstructions and source images without resolved public reuse remain outside the distributable assets. Review copies are kept only in the local verification folder.</p><h2>Records & remaining gaps</h2><div class="actions"><a class="button secondary" href="source-records/public-source-register.json" target="_blank" rel="noopener noreferrer">Public source register ↗</a><a class="button secondary" href="docs/research-map.md" target="_blank" rel="noopener noreferrer">Text research map ↗</a></div><ul style="margin-top:2rem"><li>Six repository URLs are not anonymously accessible. Private status is reported from the supplied summary; an anonymous 404 does not independently prove visibility.</li><li>Several public repositories have no detected licence. No code or imagery from those projects is redistributed.</li><li>Hardware arXiv and earlier safety preprints have different titles from the local revisions. Links are labelled with their version context.</li><li>Current under-review statuses, final author contribution statements, examination archives and patent details need author records.</li></ul></div>`}
  function render(){const parts=(location.hash.slice(1)||'story').split('/');let next=parts[0];if(!['story','tools','thesis','sources'].includes(next))next='story';const changed=next!==page;if(changed){page=next;main.innerHTML=({story,tools,thesis,sources})[page]();document.title=`${({story:'The Story',tools:'Explore the Tools',thesis:'The Thesis',sources:'Sources & Credits'})[page]} · Below the Surface`;document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(page==='tools'){refreshCards();selectStage(selectedStage);}}const target=parts[1];if(target){const id=page==='story'?`story-${target}`:paper(target)?`paper-${target}`:`thesis-${target}`;requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView({behavior:'instant',block:'start'}));}else if(changed)window.scrollTo({top:0,behavior:'instant'});if(changed&&location.hash){main.focus({preventScroll:true});document.querySelector('#announcement').textContent=`${document.title} opened`;}}
  document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.getAttribute('href')==='#main'){e.preventDefault();main.focus({preventScroll:true});main.scrollIntoView({behavior:'instant',block:'start'});return;}if(b.dataset.repo){openRepository(b.dataset.repo,b);return}if(b.hasAttribute('data-close-dialog')){closeDialog();return}if(b.hasAttribute('data-dialog-nav')){closeDialog();return}if(b.dataset.method){const id=b.dataset.method;document.querySelectorAll('[data-method]').forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});document.querySelector('#method-panel').innerHTML=methodPanel(id);document.querySelector('#method-panel').setAttribute('aria-labelledby',`method-tab-${id}`);return}if(b.dataset.stage){selectStage(b.dataset.stage);return}if(b.dataset.group){filters.group=b.dataset.group;refreshCards();return}if(b.hasAttribute('data-reset-filters')){filters={q:'',group:'all',type:'all',access:'all'};document.querySelector('#repo-search').value='';document.querySelector('#type-filter').value='all';document.querySelector('#access-filter').value='all';refreshCards();}});
  document.addEventListener('input',e=>{if(e.target.id==='repo-search'){filters.q=e.target.value;refreshCards()}});
  document.addEventListener('change',e=>{if(e.target.id==='type-filter'){filters.type=e.target.value;refreshCards()}if(e.target.id==='access-filter'){filters.access=e.target.value;refreshCards()}});
  document.addEventListener('keydown',e=>{if(e.target.matches('[data-method]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-method]')],i=tabs.indexOf(e.target);const target=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[target].focus();tabs[target].click();}});
  dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
  window.addEventListener('hashchange',render);
  render();
})();
